<script setup lang="ts">
const api=inject<any>('adminFetch')
const data=ref<any>({items:[],total:0,unread:0}),selected=ref<any>(null)
const q=ref(''),status=ref(''),unread=ref(false),page=ref(1),pending=ref(false),error=ref('')
let timer:ReturnType<typeof setInterval>|undefined
const fmt=(s:string)=>s?new Date(s).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',dateStyle:'short',timeStyle:'short'}):'—'
const tariff=(id:string)=>({invited4:'Обычный · 1 500 ₽',promo4:'Редкий · 2 000 ₽',long6:'Легендарный · 3 000 ₽'}[id]||id)
async function load(){pending.value=true;error.value='';try{data.value=await api('/api/admin/bookings',{query:{page:page.value,pageSize:20,q:q.value,status:status.value,unread:unread.value}})}catch(e:any){error.value=e?.data?.message||'Не удалось загрузить заявки'}finally{pending.value=false}}
async function open(id:number){error.value='';try{selected.value=await api(`/api/admin/bookings/${id}`,{method:'PUT',body:{viewed:true}});await load()}catch(e:any){error.value=e?.data?.message||'Не удалось открыть заявку'}}
async function save(body:any){error.value='';try{selected.value=await api(`/api/admin/bookings/${selected.value.id}`,{method:'PUT',body});await load()}catch(e:any){error.value=e?.data?.message||'Не удалось сохранить'}}
function filter(){page.value=1;load()}
onMounted(()=>{load();timer=setInterval(()=>{if(document.visibilityState==='visible')load()},30000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template>
 <section><div class="mb-4 flex flex-wrap justify-between gap-3"><h2 class="text-3xl">Заявки <span class="text-lg text-ash">Непрочитанных: {{data.unread}}</span></h2><button class="btn-ghost" :disabled="pending" @click="load">Обновить</button></div><form class="card mb-5 grid items-end gap-3 sm:grid-cols-2 lg:grid-cols-4" @submit.prevent="filter"><label>Имя или телефон<input v-model="q" class="input mt-1" type="search" maxlength="120"/></label><label>Статус<select v-model="status" class="input mt-1"><option value="">Все</option><option value="new">Новая</option><option value="confirmed">Подтверждена</option><option value="cancelled">Отменена</option></select></label><label class="flex min-h-11 items-center gap-2"><input v-model="unread" type="checkbox"/> Только непрочитанные</label><button class="btn-primary" :disabled="pending">Найти</button></form><p v-if="error" role="alert" class="mb-4 text-red-300">{{error}}</p><p v-if="pending" role="status" class="mb-3 text-ash">Обновляем…</p><div class="grid items-start gap-5 lg:grid-cols-2"><div class="space-y-3"><button v-for="b in data.items" :key="b.id" class="card w-full text-left" :class="!b.viewed_at&&'border-candle'" @click="open(b.id)"><span class="flex flex-wrap justify-between gap-2"><strong>{{b.name}}</strong><span class="text-sm text-ash">#{{b.id}} · {{fmt(b.created_at)}}</span></span><span class="mt-2 block">{{b.contact}}</span><span class="mt-2 block text-sm text-ash">{{!b.viewed_at?'● Непрочитанная':'Просмотрена'}} · {{b.status==='new'?'Новая':b.status==='confirmed'?'Подтверждена':'Отменена'}}</span></button><p v-if="!pending&&!data.items.length" class="card text-ash">Заявок по выбранным условиям нет.</p><div class="flex items-center justify-between gap-2"><button class="btn-ghost" :disabled="page===1||pending" @click="page--;load()">Назад</button><span>{{page}} · Всего {{data.total}}</span><button class="btn-ghost" :disabled="page*20>=data.total||pending" @click="page++;load()">Далее</button></div></div><article v-if="selected" class="card space-y-4"><h3 class="break-words text-3xl">{{selected.name}}</h3><a :href="`tel:${selected.contact}`" class="inline-block text-xl text-candle">{{selected.contact}}</a><dl class="space-y-2 text-sm"><div><dt class="text-ash">Получена (Москва)</dt><dd>{{fmt(selected.created_at)}}</dd></div><div><dt class="text-ash">Тариф / мест</dt><dd>{{tariff(selected.tariff)}} / {{selected.players}}</dd></div><div><dt class="text-ash">Пригласил</dt><dd>{{selected.invited_by||'Не указан'}}</dd></div><div><dt class="text-ash">Источник</dt><dd>{{selected.source==='quick'?'Короткая форма':'Расширенная форма'}}</dd></div><div><dt class="text-ash">Сообщение</dt><dd class="whitespace-pre-line break-words">{{selected.comment||'Без сообщения'}}</dd></div></dl><label class="block">Статус<select v-model="selected.status" class="input mt-1"><option value="new">Новая</option><option value="confirmed">Подтверждена</option><option value="cancelled">Отменена</option></select></label><label class="block">Заметка администратора<textarea v-model="selected.admin_note" class="input mt-1" rows="4" maxlength="4000"/></label><div class="flex flex-wrap gap-3"><button class="btn-primary" @click="save({status:selected.status,admin_note:selected.admin_note})">Сохранить</button><button class="btn-ghost" @click="save({viewed:!selected.viewed_at})">{{selected.viewed_at?'Пометить непрочитанной':'Пометить прочитанной'}}</button></div></article></div></section>
</template>
